import yaml
import os
import re
from auto_config.generator.utils.shell_utils import execute_sudo_command
from auto_config.generator.utils.logger import logger


def merge_dictionaries(default_dictionary, profile_dictionary):
    """
    :param default_dictionary: nested dictionary with default and general parameters.
    :param profile_dictionary: nested dictionary with required parameters.
    :return: dictionary generator with merged key-value pairs.

    For the same nesting level, function returns merged dictionaries, if the keys are not duplicated.
    Whether keys are duplicated, it prioritizes profile_dictionary over default_dictionary.

    WARNING: Profile_dict 's values will always shadow values for the same key of default_dictionary, eg.:
    default_dictionary[key] = {a: b, c: d}
    profile_dictionary[key] = 'b'
    will result in merged_dictionary[key] = 'b'
    """
    all_keys = set(default_dictionary.keys()).union(profile_dictionary.keys())
    for key in all_keys:
        if key in default_dictionary and key in profile_dictionary:

            # merge two dictionaries by recursive call
            if isinstance(default_dictionary[key], dict) and isinstance(profile_dictionary[key], dict):
                yield key, dict(merge_dictionaries(default_dictionary[key], profile_dictionary[key]))

            # one of value is not a dictionary -> yield profile_dictionary[key]
            else:
                yield key, profile_dictionary[key]

        elif key in default_dictionary:
            yield key, default_dictionary[key]
        else:
            yield key, profile_dictionary[key]


def flatten_list_if_single_element(list_):
    if isinstance(list_, list) and len(list_) == 1:
        return list_[0]
    return list_


def sorting_key(string):
    return ''.join([format(int(x), '05d') if x.isdigit() else x for x in re.split(r'(\d+)', string)])


def get_yaml_file(filepath, loader=yaml.BaseLoader):
    with open(filepath) as f:
        yaml_file = yaml.load(f, Loader=loader)
    return yaml_file


def save_yaml_file(output_dir, filename, content):
    with open(file=os.path.join(output_dir, filename), mode='w') as f:
        yaml.dump(content, f)


def get_duplex_mode(enb_config, build):
    if build is None or re.match(r'FL*', build, re.I):
        return 'FDD'
    for enb_ent in enb_config.values():
        for cell in enb_ent['cells'].values():
            if 'earfcn_dl' in cell or 'earfcn_ul' in cell:
                return 'FDD'
    return 'TDD'


def is_nr(enb_ent):
    if is_type_sa(enb_ent) or is_type_sa_nsa(enb_ent):
        return True
    return False


def is_type_sa(enb_ent):
    if 'type' in enb_ent and enb_ent['type'] == 'SA':
        return True
    return False


def is_type_sa_nsa(enb_ent):
    if 'type' in enb_ent and enb_ent['type'] == 'SA+NSA':
        return True
    return False


def check_install_emssim():
    ret = execute_sudo_command('dpkg -l emssim')
    if ret != 0:
        execute_sudo_command('apt install -y emssim')


def get_env(var):
    env_var = os.environ.get(var, '')
    return int(env_var) >= 1 if env_var.isdigit() else False


def validate_custom_params_correctness(custom_params, parsed_pddb):
    for dn, params in custom_params.items():
        moc_name = dn.split('/')[-1].split('-')[0]
        param_to_delete = []
        for custom_param_name, custom_param_value in params.items():
            if custom_param_name in parsed_pddb[moc_name]:
                _check_range(moc_name, custom_param_name, custom_param_value, parsed_pddb)
            else:
                logger.warning(f"CUSTOM PARAM WARNING : Removing a param {custom_param_name} that was not found in the PDDB")
                param_to_delete.append(custom_param_name)
        if param_to_delete:
            for key in param_to_delete:
                del params[key]


def validate_custom_tnl_pattern_correctnes(enb_config_values):
    pattern = r"^TNL-\d+/IPNO-\d+/IPIF-\d+$"
    for interface, dn in enb_config_values['tnl_conf'].items():
        if not re.match(pattern, dn):
            raise ValueError(f"Wrong DN pattern for {interface} {dn} in tnl_conf section, should be eg. TNL-2/IPNO-1/IPIF-2")


def validate_provided_interfaces(intefaces_list, enb_config_values, setup_type):
    custom_intefaces_list = list(enb_config_values['tnl_conf'].keys())
    if not sorted(custom_intefaces_list) == sorted(intefaces_list):
        raise ValueError(
            f"Defined interfaces in tnl_conf {custom_intefaces_list} must be exactly the same as: {intefaces_list} for BTS {setup_type} type")


def _check_range(moc_name, custom_param_name, custom_param_value, parsed_pddb):
    CHECK_RANGE = {
        "Number": _check_range_number,
        "String": _check_range_string,
        "Boolean": _check_range_boolean,
        "Bitmask": _check_range_bitmask,
        "Enumeration": _check_range_enumeration,
    }
    param_data = parsed_pddb[moc_name][custom_param_name]
    param_type = param_data['type']
    if param_type in CHECK_RANGE:
        CHECK_RANGE[param_type](custom_param_value, param_data)
    elif param_type == "Structure":
        if not isinstance(custom_param_value, dict):
            raise TypeError(f"CUSTOM PARAM WARNING : {custom_param_name} value should be a dict")
        subparam_to_delete = []
        for custom_subparam_name, custom_subparam_value in custom_param_value.items():
            subparams = parsed_pddb[moc_name][custom_param_name]['struct']
            if custom_subparam_name in subparams:
                subparam_data = parsed_pddb[moc_name][custom_param_name]['struct'][custom_subparam_name]
                if subparam_data['type'] in CHECK_RANGE:
                    CHECK_RANGE[subparam_data['type']](custom_subparam_value, subparam_data)
            else:
                logger.warning(f"CUSTOM PARAM WARNING : Removing a subparam {custom_subparam_name} that was not found in the PDDB")
                subparam_to_delete.append(custom_subparam_name)
        if subparam_to_delete:
            for key in subparam_to_delete:
                del custom_param_value[key]
    else:
        raise Exception(f"Wrong type for {custom_param_name}: {param_type}")


def _check_range_enumeration(custom_param_value, param_data):
    range_value = param_data['range']
    param_value = custom_param_value
    wtrans = param_data['wtrans']
    if wtrans != " return shift ":
        raise Exception(f"Wrong wtrans(enumeration): {wtrans}")
    values = range_value.split("),")
    for i, val in enumerate(values):
        if val[-1] != ")":
            values[i] += ")"
    values = [re.search(r"^(.*)\s\(\d+\)$", x).group(1) for x in values]
    if isinstance(param_value, list) or isinstance(param_value, tuple):
        for param_value_item in param_value:
            param_value_item = str(param_value_item)
            if param_value_item not in values:
                raise Exception(f"Wrong value(enumeration-list): val={param_value_item}, values={values}")
    else:
        param_value = str(param_value)
        if param_value not in values:
            raise Exception(f"Wrong value(enumeration): val={param_value}, values={values}")


def _check_range_boolean(custom_param_value, param_data):
    param_value_list = custom_param_value
    if not isinstance(param_value_list, list):
        param_value_list = [param_value_list]
    for param_value in param_value_list:
        if param_value != "true" and param_value != "false":
            raise Exception(f"Wrong value(boolean): val={param_value}")


def _check_range_bitmask(custom_param_value, param_data):
    wtrans = param_data['wtrans']
    if wtrans != " return shift ":
        raise Exception(f"Wrong wtrans(bitmask): {wtrans}")


def _check_range_number(custom_param_value, param_data):
    range_value = param_data['range']
    param_value_list = custom_param_value
    wtrans = param_data['wtrans']
    srch = re.search(r"^([-.0-9]+)\.\.\.([-.0-9]+).*step [-.0-9]+", range_value)
    if not isinstance(param_value_list, list):
        param_value_list = [param_value_list]
    if srch:
        for param_value in param_value_list:
            str_min, str_max = (srch.group(1), srch.group(2))
            str_min = _transform_by_wtrans(str_min, wtrans)
            str_max = _transform_by_wtrans(str_max, wtrans)
            if "." in str_min or "." in str_max:
                dec_param_value = float(param_value)
                dec_min = float(str_min)
                dec_max = float(str_max)
            else:
                dec_param_value = int(param_value)
                dec_min = int(str_min)
                dec_max = int(str_max)

            if dec_param_value < dec_min or dec_param_value > dec_max:
                if 'special' in param_data:
                    str_special = param_data['special']
                    if "." in str_special:
                        dec_special = float(str_special)
                    else:
                        dec_special = int(str_special)
                    if dec_special != dec_param_value:
                        raise Exception(f"Wrong value(number-special): val={param_value}, min={str_min}, max={str_max}, special={str_special}")
                else:
                    raise Exception(f"Wrong value(number): val={param_value}, min={str_min}, max={str_max}")
    else:
        raise Exception(f"Wrong range(number): {range_value}")


def _check_range_string(custom_param_value, param_data):
    range_value = param_data['range']
    param_value_list = custom_param_value
    if not isinstance(param_value_list, list):
        param_value_list = [param_value_list]
    srch = re.search(r"^([0-9]+)\.\.\.([0-9]+) characters", range_value)
    if srch:
        for param_value in param_value_list:
            r_min, r_max = (int(srch.group(1)), int(srch.group(2)))
            if isinstance(param_value, list) or isinstance(param_value, tuple):
                for param_value_item in param_value:
                    if len(param_value_item) < r_min or len(param_value_item) > r_max:
                        raise Exception(f"Wrong value(string-list): val={param_value}, min_len={r_min}, max_len={r_max}")
            else:
                if len(param_value) < r_min or len(param_value) > r_max:
                    raise Exception(f"Wrong value(string): val={param_value}, min_len={r_min}, max_len={r_max}")
    else:
        raise Exception(f"Wrong range(string): {range_value}")


def _transform_by_wtrans(value, wtrans):
    if value == '':
        return value
    wtrans_srch = re.search(r'return (.*\$in.*);', wtrans)
    if wtrans_srch:
        wtrans_sub = re.sub(r'\$in', value, wtrans_srch.group(1))
        new_value = str(round(eval(wtrans_sub), 5))
        new_value = re.sub(r'\.0+$', '', new_value)
        value = new_value
    return value
